  function isActive(){try{if(typeof activeTier!=='undefined'&&typeof activeIndex!=='undefined'&&typeof FEATURE_DATA!=='undefined'){var f=(FEATURE_DATA[activeTier]||[])[activeIndex];if(f&&f.feature)return f.feature===FEATURE;}}catch(e){}var x=document.querySelector('#sidebarList .feat-item.active .label'),t=x?x.textContent.replace(/\s*(AI|BETA)\s*$/,'').trim():'';return t===FEATURE;}
