  function portfolioMapHtml(p){var pts=DATA.filter(function(x){return MAP_COORDS[x.id];}).map(function(x){var c=MAP_COORDS[x.id],q=mapPoint(c[0],c[1]),on=x.id===p.id;return'<g class="gaw-map-point '+(on?'is-selected':'')+'" data-gaw-map-id="'+esc(x.id)+'" transform="translate('+(q.x*10).toFixed(1)+' '+(q.y*5).toFixed(1)+')" tabindex="0" role="button" aria-label="Open '+esc(x.name)+'"><circle r="8"></circle><circle r="3.6"></circle><text x="11" y="3">'+esc(x.name.replace(/ HAC 2026$/,''))+'</text></g>';}).join('');return'<div class="gaa-map-wrap"><div class="snw-map gaw-map"><span class="gaa-map-label">Country programmes in register · selected: '+esc(p.name)+'</span><svg viewBox="0 0 1000 500" preserveAspectRatio="none" role="img" aria-label="Global Aid country programme map">'+pts+'</svg><div class="gaa-map-key"><span><i class="sel"></i>Selected country programme</span><span><i></i>Tracked country programme</span></div></div></div>';}
