  function aidHeatRecords(p){return DATA.filter(function(x){return AID_COUNTRIES[x.id];}).map(function(x){var on=x.id===p.id,v=Number(x.requirement)||0,color=on?'#d94e35':v>=800000000?'#397ca5':v>=300000000?'#6f9eb8':'#a7c4d3';return{country:AID_COUNTRIES[x.id],color:color,label:on?'Selected programme':'Published programme requirement',detail:money(x.requirement)+' · '+x.agency,focus:on,id:x.id};});}
