  function portfolioBarRows(list,valueLabel){var max=Math.max.apply(null,list.map(function(x){return x.value;}).concat([1]));return list.map(function(x){return'<div class="gaa-port-bar"><label title="'+esc(x.name)+'">'+esc(x.name)+'</label><span class="gaa-port-track"><i class="gaa-port-fill" style="width:'+Math.max(3,Math.round(x.value/max*100))+'%"></i></span><b>'+esc(valueLabel(x))+'</b></div>';}).join('');}
  function portfolioVisualsHtml(p){var asks=sortedAppeals().map(function(x){return{name:x.name.replace(/\s+(20\d\d|2025–2028)$/,''),value:x.requirement};}),ag=agencyCounts();return'<div class="gaa-portfolio-strip"><div class="gaa-port-kpi"><label>2026 UN appeal</label><strong>$33B</strong><span>135M people targeted</span></div><div class="gaa-port-kpi"><label>UNICEF HAC 2026</label><strong>$7.66B</strong><span>35 published appeals</span></div><div class="gaa-port-kpi"><label>IDA21 package</label><strong>$100B</strong><span>Separate concessional facility</span></div><div class="gaa-port-kpi"><label>2024 DAC ODA</label><strong>$214.6B</strong><span>Final OECD · −6.0% real</span></div></div><div class="gaa-visual-grid">'+portfolioMapHtml(p)+'<div class="gaa-chart-stack"><section class="gaa-port-chart"><div class="gaa-port-title"><b>Largest published requirements</b><span>Appeals only</span></div><div class="gaa-port-bars">'+portfolioBarRows(asks,function(x){return money(x.value);})+'</div></section><section class="gaa-port-chart"><div class="gaa-port-title"><b>Programme coverage by institution</b><span>'+DATA.length+' records</span></div><div class="gaa-port-bars">'+portfolioBarRows(ag,function(x){return x.value;})+'</div></section></div></div>';}
  function feedRows(list){return list.map(function(p){return'<tr tabindex="0" role="row" draggable="true" data-gaw-drag="1" data-gaw-id="'+esc(p.id)+'"><td><span class="gaw-program" title="'+esc(p.name)+'">'+esc(p.name)+'</span><span class="gaw-program-sub">'+esc(p.type)+'</span></td><td><span class="gaw-program">'+esc(p.agency)+'</span><span class="gaw-program-sub">'+esc(p.region)+'</span></td><td class="gaw-num">'+money(p.requirement)+'</td><td class="gaw-num">'+compact(p.target)+'</td><td><span class="gaw-status">'+esc(p.status)+'</span></td><td class="gaw-num">'+esc(p.dataThrough)+'</td></tr>';}).join('');}
