  function feedHtml(){return'<div class="gaw-mast"><div class="gaw-title"><h2>Global Aid Operations Register</h2><p>Official appeals + financing facilities · source-linked · dated snapshots</p></div><div class="gaw-stat"><strong>'+DATA.length+'</strong><span>programmes</span></div><div class="gaw-stat"><strong>8</strong><span>institutions</span></div><div class="gaw-stat"><strong>7</strong><span>regions</span></div><div class="gaw-stat"><strong>'+DATA.length+'/'+DATA.length+'</strong><span>source-linked</span></div></div><div class="gaw-context"><div class="gaw-context-item"><label>2026 UN appeal</label><strong>$33B</strong><span>135M people targeted</span></div><div class="gaw-context-item"><label>UNICEF HAC 2026</label><strong>$7.66B</strong><span>35 appeals · 73M people</span></div><div class="gaw-context-item"><label>IDA21 package</label><strong>$100B</strong><span>78 countries · FY2025–28</span></div><div class="gaw-context-item"><label>2024 DAC ODA</label><strong>$214.6B</strong><span>−6.0% real terms · final OECD</span></div></div><div class="gaw-controls"><input class="gaw-search" type="search" aria-label="Search aid programmes" placeholder="Search programme, institution, country or sector"><select class="gaw-select gaw-region"><option value="">All regions</option>'+Array.from(new Set(DATA.map(function(p){return p.region;}))).sort().map(function(x){return'<option>'+esc(x)+'</option>';}).join('')+'</select><select class="gaw-select gaw-agency"><option value="">All institutions</option>'+Array.from(new Set(DATA.map(function(p){return p.agency;}))).sort().map(function(x){return'<option>'+esc(x)+'</option>';}).join('')+'</select><select class="gaw-select gaw-type-filter"><option value="">All programme types</option>'+Array.from(new Set(DATA.map(function(p){return p.type;}))).sort().map(function(x){return'<option>'+esc(x)+'</option>';}).join('')+'</select></div><div class="gaw-viewbar"><button class="gaw-view active" type="button" data-gaw-view="programmes">Programme register</button><button class="gaw-view" type="button" data-gaw-view="wire">Live aid wire</button><span class="gaw-view-meta"><b data-gaw-count>'+DATA.length+'</b> records · click or drag into AI Chat</span></div><div class="gaw-panel" data-gaw-panel="programmes">'+chartBand()+'<div class="gaw-tablewrap"><table aria-label="Global aid programme register"><colgroup><col style="width:29%"><col style="width:18%"><col style="width:13%"><col style="width:12%"><col style="width:15%"><col style="width:13%"></colgroup><thead><tr><th>Programme</th><th>Institution / region</th><th>Requirement</th><th>People target</th><th>Record status</th><th>Data through</th></tr></thead><tbody>'+feedRows(DATA)+'</tbody></table></div></div><div class="gaw-panel" data-gaw-panel="wire" hidden><div class="gaw-wire-state">Verified programme updates shown immediately · GDELT humanitarian wire refreshes when available</div><div class="gaw-tablewrap"><table class="gaw-wire-table" aria-label="Global aid wire"><colgroup><col style="width:12%"><col style="width:55%"><col style="width:17%"><col style="width:16%"></colgroup><thead><tr><th>Recorded</th><th>Development</th><th>Source</th><th>Geography</th></tr></thead><tbody>'+wireRows(WIRE)+'</tbody></table></div></div>';}
  function analyticalBrief(p){return p.brief;}
