  function coverageHtml(p){var c=pct(p);if(c==null)return'<div class="gaa-coverage"><div class="gaa-coverage-top"><span>Funding coverage</span><b>Not stated in cited summary</b></div><div class="gaa-covertrack"><i class="gaa-coverfill" style="width:0"></i></div><p>'+esc(p.fundingNote)+'</p></div>';return'<div class="gaa-coverage"><div class="gaa-coverage-top"><span>Reported funding / financing component</span><b>'+money(p.funded)+' · '+c+'%</b></div><div class="gaa-covertrack"><i class="gaa-coverfill" style="width:'+c+'%"></i></div><p>'+esc(p.fundingNote)+'</p></div>';}
  function overviewHtml(p){return'<section class="gaa-section"><div class="gaa-sechead"><b>Programme snapshot</b><span>Data through '+esc(p.dataThrough)+'</span></div><div class="gaa-kpis"><div class="gaa-kpi"><label>Published requirement</label><strong>'+money(p.requirement)+'</strong><span>'+(p.requirement==null?'Not stated in the cited summary':'Requested financing; not cash received')+'</span></div><div class="gaa-kpi"><label>People targeted</label><strong>'+compact(p.target)+'</strong><span>'+(p.target==null?'Service-specific targets are shown below':'Published planning target')+'</span></div><div class="gaa-kpi"><label>People in need / scope</label><strong>'+compact(p.need)+'</strong><span>'+esc(p.geography)+'</span></div><div class="gaa-kpi"><label>Operating period</label><strong>'+esc(p.period)+'</strong><span>'+esc(p.status)+'</span></div></div></section><div class="gaa-two-col"><section class="gaa-section"><div class="gaa-sechead"><b>Funding position</b><a href="'+esc(p.source)+'" target="_blank" rel="noreferrer">Inspect source ↗</a></div>'+coverageHtml(p)+'</section><div><section class="gaa-section"><div class="gaa-update"><label>Latest verified record · '+esc(p.latestDate)+'</label><p>'+esc(p.latest)+'</p></div></section><section class="gaa-section"><div class="gaa-ai"><label>AI analyst brief</label><p>'+esc(analyticalBrief(p))+'</p></div></section></div></div>';}
  function targetsHtml(p){return'<div class="gaa-two-col"><section class="gaa-section"><div class="gaa-sechead"><b>Published programme indicators</b><span>Do not sum overlapping reach</span></div>'+indicatorHtml(p)+'</section><div><section class="gaa-section"><div class="gaa-sechead"><b>Priority sectors</b><span>Named in programme record</span></div><div class="gaa-sectorchips">'+p.sectors.map(function(x){return'<span class="gaa-chip">'+esc(x)+'</span>';}).join('')+'</div></section><section class="gaa-section"><div class="gaa-sechead"><b>Delivery controls</b><span>What the record establishes</span></div><div class="gaa-update"><label>Measurement discipline</label><p>Targets are planning figures. Reached people and delivered funds require dated implementation reporting.</p></div></section></div></div><section class="gaa-section"><div class="gaa-sechead"><b>Delivery architecture</b><span>Recorded programme model</span></div><div class="gaa-grid"><div class="gaa-cell"><label>Coordinator</label><p>'+esc(p.coordinator)+'</p></div><div class="gaa-cell"><label>Delivery model</label><p>'+esc(p.delivery)+'</p></div><div class="gaa-cell"><label>Geographic scope</label><p>'+esc(p.geography)+'</p></div><div class="gaa-cell"><label>Operating period</label><p>'+esc(p.period)+' · '+esc(p.status)+'</p></div></div></section>';}
  function fundingHtml(p){return'<section class="gaa-section"><div class="gaa-sechead"><b>Funding instrument</b><span>'+esc(p.type)+'</span></div><div class="gaa-grid"><div class="gaa-cell"><label>Published requirement / package</label><p>'+money(p.requirement)+'</p></div><div class="gaa-cell"><label>Reported funding component</label><p>'+money(p.funded)+'</p></div><div class="gaa-cell"><label>Coverage treatment</label><p>'+(pct(p)==null?'No percentage is shown without a dated receipt total.':'Calculated directly from the displayed requirement and funding values: '+pct(p)+'%.')+'</p></div><div class="gaa-cell"><label>Reporting caveat</label><p>'+esc(p.fundingNote)+'</p></div></div></section><div class="gaa-two-col"><section class="gaa-section"><div class="gaa-sechead"><b>Programme chronology</b><span>Verified milestones</span></div><div class="gaa-timeline">'+p.milestones.map(function(x){return'<div class="gaa-time"><label>'+esc(x[0])+'</label><p>'+esc(x[1])+'</p></div>';}).join('')+'</div></section><section class="gaa-section"><div class="gaa-sechead"><b>Source record</b><span>Attributable inputs</span></div><div class="gaa-sources"><a class="gaa-source" href="'+esc(p.source)+'" target="_blank" rel="noreferrer"><b>'+esc(p.sourceLabel)+'</b><span>Open official record ↗</span></a></div><div class="gaa-ai" style="margin-top:10px"><label>Interpretation rule</label><p>Humanitarian requirements, reported receipts and development-finance packages remain separate instruments and are not aggregated.</p></div></section></div>';}
  function analyticsHtml(p){return'<div class="gaw-a"><header class="gaa-head"><i class="gaa-mark"></i><div class="gaa-headcopy"><h2>'+esc(p.name)+'</h2><p>'+esc(p.agency)+' · '+esc(p.region)+' · data through '+esc(p.dataThrough)+'</p></div><span class="gaa-state">'+esc(p.status)+'</span></header>'+portfolioVisualsHtml(p)+'<nav class="gaa-tabs" aria-label="Aid analytics views"><button class="gaa-tab active" type="button" data-gaa-tab="overview">Overview</button><button class="gaa-tab" type="button" data-gaa-tab="targets">Targets & delivery</button><button class="gaa-tab" type="button" data-gaa-tab="funding">Funding & sources</button></nav><div class="gaa-view" data-gaa-view="overview">'+overviewHtml(p)+'</div><div class="gaa-view" data-gaa-view="targets" hidden>'+targetsHtml(p)+'</div><div class="gaa-view" data-gaa-view="funding" hidden>'+fundingHtml(p)+'</div><div class="gaa-actions"><button class="gaa-chat" type="button" data-gaw-chat>Open AI Chat</button><span class="gaa-method">Drag a feed record into chat only when context is needed.</span></div></div>';}
